"""DACON inference entry point (generated by src/build_submission.py)."""

from pathlib import Path
import importlib.util
import subprocess
import sys

HERE = Path(__file__).resolve().parent
REQUIRED = ['rapidfuzz', 'lightgbm', 'transformers']


def ensure_packages():
    """Install bundled wheels offline for anything the install step did not provide."""
    missing = [p for p in REQUIRED if importlib.util.find_spec(p) is None]
    if missing and (HERE / "wheels").exists():
        subprocess.run([sys.executable, "-m", "pip", "install", "--no-index",
                        "--find-links", str(HERE / "wheels"), *missing], check=False)


ensure_packages()

import joblib  # noqa: E402
import pandas as pd  # noqa: E402

sys.path.insert(0, str(HERE / "model" / "src"))
from models.ranked_llm import from_artifacts  # noqa: E402


def run(test_path="data/test.csv", catalog_path="data/vessel_catalog.csv",
        output_path="output/submission.csv"):
    test = pd.read_csv(test_path, encoding="utf-8-sig")
    catalog = pd.read_csv(catalog_path, encoding="utf-8-sig")
    if test["sample_id"].isna().any() or not test["sample_id"].is_unique:
        raise ValueError("test.csv sample_id must be non-null and unique")
    art = joblib.load(HERE / "model" / "artifacts.joblib")
    preds = from_artifacts(art, catalog)(test)
    valid_ids = set(catalog["vessel_id"].astype(str))
    if len(preds) != len(test) or not set(map(str, preds)) <= valid_ids:
        raise ValueError("Invalid catalog predictions")
    out = Path(output_path)
    out.parent.mkdir(parents=True, exist_ok=True)
    pd.DataFrame({"sample_id": test["sample_id"], "target_vessel_id": preds}).to_csv(
        out, index=False, encoding="utf-8")
    print(f"Saved {len(preds)} predictions to {out}")


if __name__ == "__main__":
    run()
